-- Mount Hyjal: creature abilities
-- Most of the zone's creatures (the Twilight's Hammer, the Firelands invaders, the furbolgs and Hyjal's wildlife) had no AI or ran
-- classic rows: port their abilities from the Cataclysm data, falling back to the classic data where Cataclysm has none, keeping
-- the quest scripts already in place; gossip and quest reward scripts of the references are left out. The creatures no reference
-- scripts cast their sniffed spells (creature_template spell1-8).

SET @ENTRIES := '7463,10201,38913,38915,38926,38951,39348,39436,39437,39445,39637,39642,39643,39646,39724,39726,39749,39756,39843,39844,39846,39869,39925,39931,40066,40185,40229,40278,40333,40336,40403,40427,40463,40464,40536,40561,40562,40563,40573,40709,40713,40755,40767,40814,40833,40838,40843,40844,40857,40882,40956,40998,41008,41028,41029,41030,41084,41226,41396,41502,41563,41565,42657,42658,42659,42660,42663,42664,43427,46911,46925,46991,48725,50053,50057,50058,50083';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '39939,40123,46910,52219,52289,52300,52557,52649,52670,52749,52766,52791,52794,52795,52816,52847,52853,53264,53265,53267,53271,53823,54317,54362';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
